import {
  InsufficientStockError,
  InvalidTransitionError,
  NotFoundError,
  ValidationError,
} from "../domain/errors";
import { Order, type OrderLine, type OrderSnapshot, type OrderState } from "../domain/order";
import type { Product } from "../domain/product";
import type {
  Clock,
  IdGenerator,
  OrderRepository,
  ProductRepository,
} from "../domain/repositories";

export interface PlaceOrderCommand {
  customerId: string;
  items: { productId: string; quantity: number }[];
}

export class OrderService {
  constructor(
    private readonly orders: OrderRepository,
    private readonly products: ProductRepository,
    private readonly ids: IdGenerator,
    private readonly clock: Clock,
  ) {}

  /**
   * Places an order and reserves stock for every line. Either all lines are
   * reserved or none are: availability is checked for the whole order first.
   */
  placeOrder(command: PlaceOrderCommand): OrderSnapshot {
    if (command.items.length === 0) {
      throw new ValidationError("An order must contain at least one item");
    }

    const resolved: { product: Product; quantity: number }[] = [];
    for (const item of command.items) {
      const product = this.requireProduct(item.productId);
      resolved.push({ product, quantity: item.quantity });
    }

    const lines: OrderLine[] = resolved.map(({ product, quantity }) => ({
      productId: product.id,
      quantity,
      unitPriceCents: product.priceCents,
    }));
    // Validates quantities and duplicate lines before any stock is touched.
    const order = new Order(this.ids.next(), command.customerId, lines, this.clock.now());

    for (const { product, quantity } of resolved) {
      if (!product.canReserve(quantity)) {
        throw new InsufficientStockError(product.id, quantity, product.available);
      }
    }
    for (const { product, quantity } of resolved) {
      product.reserve(quantity);
      this.products.save(product);
    }

    this.orders.save(order);
    return order.toSnapshot();
  }

  getOrder(id: string): OrderSnapshot {
    return this.requireOrder(id).toSnapshot();
  }

  listOrders(state?: OrderState): OrderSnapshot[] {
    return this.orders.findAll(state).map((o) => o.toSnapshot());
  }

  /** Moves the order to the given state, enforcing the fulfilment sequence. */
  transition(id: string, target: OrderState): OrderSnapshot {
    if (target === "cancelled") return this.cancel(id);

    const order = this.requireOrder(id);
    order.advanceTo(target, this.clock.now());

    if (target === "shipped") {
      for (const line of order.lines) {
        const product = this.requireProduct(line.productId);
        product.consumeReserved(line.quantity);
        this.products.save(product);
      }
    }

    this.orders.save(order);
    return order.toSnapshot();
  }

  /** Moves the order one step forward in the fulfilment sequence. */
  advance(id: string): OrderSnapshot {
    const order = this.requireOrder(id);
    const next = order.nextState();
    if (!next) {
      throw new InvalidTransitionError(
        `Order ${id} in state '${order.state}' cannot be advanced any further`,
      );
    }
    return this.transition(id, next);
  }

  cancel(id: string): OrderSnapshot {
    const order = this.requireOrder(id);
    order.cancel(this.clock.now());

    for (const line of order.lines) {
      const product = this.requireProduct(line.productId);
      product.release(line.quantity);
      this.products.save(product);
    }

    this.orders.save(order);
    return order.toSnapshot();
  }

  private requireOrder(id: string): Order {
    const order = this.orders.findById(id);
    if (!order) throw new NotFoundError(`Order ${id} not found`);
    return order;
  }

  private requireProduct(id: string): Product {
    const product = this.products.findById(id);
    if (!product) throw new NotFoundError(`Product ${id} not found`);
    return product;
  }
}

